// Deliver what was just claimed, for EVERY item. A Code node left in the default
// "Run Once for All Items" mode that reads $json would deliver the first reminder and
// silently drop the other eleven — the easiest way there is to break a fan-out.
const claims = $input.all();
const asked = $('When called by a sender').all();
// n8n blocks $env in Code nodes unless N8N_BLOCK_ENV_ACCESS_IN_NODE=false (the deploy compose
// sets it; a default local install does not). Read it defensively, so a blocked env means
// "no transport configured" rather than a thrown node that strands every claim.
let token = '';
try { token = $env.TELEGRAM_BOT_TOKEN || ''; } catch (e) { token = ''; }

const out = [];
for (let i = 0; i < claims.length; i++) {
  const req = (asked[i] || asked[0] || {}).json || {};
  const row = (claims[i] || {}).json || {};
  const res = row.result || {};
  const echo = { appointment_id: req.appointment_id, recipient: req.recipient, kind: req.kind };
  const fail = (reason, log_id, release, detail) =>
    out.push({ json: { ok: false, sent: false, reason, log_id: log_id || null,
                       release: release === true, detail: detail || null, echo } });

  if (row.error !== undefined) { fail('db_unavailable'); continue; }
  if (!res.found)              { fail('appointment_not_found'); continue; }
  if (!res.chat_id)            { fail('no_recipient'); continue; }      // unclaimed: retry later
  if (!res.claimed) {
    const suppressed = ['booked', 'reminder_24h', 'reminder_1h'].indexOf(req.kind) >= 0
                       && res.status !== 'confirmed';
    // Not claimed because someone got there first, or because the appointment stopped being
    // confirmed. The second is a suppression, not a duplicate — say which.
    out.push({ json: { ok: true, sent: false, reason: suppressed ? 'not_confirmed' : 'already_sent',
                       log_id: null, release: false, detail: null, echo } });
    continue;
  }
  if (res.chat_id === 'manager-desk') {
    // The COALESCE placeholder: no MANAGER_TELEGRAM_CHAT_ID is configured. The alert stays
    // recorded — that audit trail is the point — but there is nowhere to send it, and POSTing
    // a placeholder chat id just 400s, releases the claim and re-sends every sweep, forever.
    out.push({ json: { ok: true, sent: false, reason: 'no_manager_chat', log_id: res.log_id,
                       release: false, detail: 'logged, no manager chat configured', echo } });
    continue;
  }
  if (!token) {
    // Claimed and recorded, but there is no bot to send through. The salon's audit trail does
    // not depend on one being wired up.
    out.push({ json: { ok: true, sent: false, reason: 'no_transport', log_id: res.log_id,
                       release: false, detail: 'logged, no transport configured', echo } });
    continue;
  }
  try {
    await this.helpers.httpRequest({
      method: 'POST', url: `https://api.telegram.org/bot${token}/sendMessage`, json: true,
      body: { chat_id: res.chat_id, text: String(req.text || '').slice(0, 3500) },
    });
    out.push({ json: { ok: true, sent: true, reason: 'delivered', log_id: res.log_id,
                       release: false, detail: 'delivered', echo } });
  } catch (e) {
    fail('send_failed', res.log_id, true);      // give the claim back
  }
}
if (out.length === 0) out.push({ json: { ok: false, sent: false, reason: 'invalid_input',
                                         log_id: null, release: false, detail: null, echo: {} } });
return out;

parameters.query:
-- A claim that could not be delivered must be given back, or the notice is marked sent
-- forever and never arrives. Deleting it lets the next run try again.
WITH del AS (
  DELETE FROM notification_log WHERE id = $1::bigint AND $2::boolean = true RETURNING id
), upd AS (
  UPDATE notification_log SET detail = $3::text
  WHERE id = $1::bigint AND $2::boolean = false AND $3::text IS NOT NULL RETURNING id
)
SELECT json_build_object('released', (SELECT count(*) FROM del) > 0) AS result;

