const out = $('Deliver').all().map(s => {
  const j = s.json || {};
  return { json: { ok: j.ok === true, sent: j.sent === true, reason: j.reason,
                   appointment_id: (j.echo || {}).appointment_id,
                   recipient: (j.echo || {}).recipient, kind: (j.echo || {}).kind } };
});
if (out.length === 0) out.push({ json: { ok: false, sent: false, reason: 'invalid_input' } });
return out;
